"""Export browser-readable cases generated by the offline synthetic adapter."""

from dataclasses import asdict
from datetime import date
import json
from pathlib import Path

from bloomberg_adapter import BloombergAdapter, Event, FixtureTransport, Request, RequestError
from bloomberg_adapter.adapter import HISTORICAL_REQUEST, REFDATA_SERVICE, REFERENCE_REQUEST
from engine.model import expected_tail_loss

EQUITIES = ("DEMO_ALPHA US Equity", "DEMO_MAPLE CN Equity")
FX = "DEMO_USDCAD Curncy"
START = date(2025, 1, 2)
END = date(2025, 6, 30)
CLOSE = ("PX_LAST",)


class EntitlementDenied(FixtureTransport):
    def events(self, request, correlation_id):
        yield Event("REQUEST_STATUS", correlation_id, ({
            "reason": {"category": "NOT_ENTITLED", "message": "Synthetic entitlement denial"},
        },))


def render(id_, label, request, **call):
    client = call.pop("client")
    as_of = call.get("as_of")
    request_view = {"service": request.service, "operation": request.operation, **request.parameters()}
    if as_of:
        request_view["valuation_date"] = as_of
    try:
        result = (client.reference(request.securities, request.fields, **call) if as_of else
                  client.historical(request.securities, request.fields, start=request.start, end=request.end))
        response = {
            "source": asdict(result.provenance.source),
            "observations": [
                {"security": row.security, "field": row.field, "value": row.value, "date": row.as_of}
                for row in result.observations[:8]
            ],
            "observations_total": len(result.observations),
            "issues": [asdict(issue) for issue in result.issues],
        }
        status = "issue" if result.issues else "ok"
        summary = f"{len(result.observations)} accepted observations · {len(result.issues)} issues"
    except RequestError as error:
        status, summary = "issue", "Request rejected · 0 observations accepted"
        response = {"source": asdict(error.provenance.source), "observations_total": 0,
                    "issues": [asdict(error.issue)]}
    return {"id": id_, "label": label, "request": request_view,
            "response": response, "status": status, "summary": summary}


def synthetic_risk(client):
    result = client.historical((*EQUITIES, FX), CLOSE, start=START, end=END)
    if result.issues:
        raise ValueError("Synthetic risk requires complete price and FX series")
    series = {ticker: {} for ticker in (*EQUITIES, FX)}
    for row in result.observations:
        if type(row.value) not in (float, int) or row.value <= 0:
            raise ValueError("Expected positive numeric prices and FX observations")
        series[row.security][row.as_of] = row.value
    dates = sorted(series[FX])
    if len(dates) < 20 or any(set(values) != set(dates) for values in series.values()):
        raise ValueError("Synthetic risk requires aligned observations")
    usd, cad = EQUITIES
    u = [series[usd][day] for day in dates]
    c = [series[cad][day] / series[FX][day] for day in dates]
    returns = [.6 * (u[i] / u[i-1] - 1) + .4 * (c[i] / c[i-1] - 1) for i in range(1, len(dates))]
    var, es = expected_tail_loss(returns)
    return {"price_dates_aligned": len(dates), "daily_returns": len(returns),
            "hypothetical_weights": {usd: .6, cad: .4},
            "fx_convention": "CAD per USD; CAD share price divided by same-day FX",
            "daily_var_95_loss_fraction": var, "daily_es_95_loss_fraction": es,
            "source": asdict(result.provenance.source)}


def main():
    transport = FixtureTransport()
    client = BloombergAdapter(transport)

    def reference(securities, fields):
        return Request(REFDATA_SERVICE, REFERENCE_REQUEST, securities, fields)

    scenarios = [
        render("reference", "Reference snapshot", reference(EQUITIES, ("PX_LAST", "CRNCY")), client=client, as_of=END),
        render("historical", "Historical prices and FX",
               Request(REFDATA_SERVICE, HISTORICAL_REQUEST, (*EQUITIES, FX), CLOSE, START, END), client=client),
        render("partial", "Partial coverage", reference((*EQUITIES, "DEMO_UNKNOWN US Equity"),
               ("PX_LAST", "UNSUPPORTED_FIELD")), client=client, as_of=END),
        render("stale", "Stale reference prices", reference(EQUITIES, CLOSE),
               client=client, as_of=date(2025, 7, 7)),
        render("denied", "Entitlement denied", reference(EQUITIES, CLOSE),
               client=BloombergAdapter(EntitlementDenied()), as_of=END),
    ]
    scenarios[1]["response"]["synthetic_usd_risk"] = synthetic_risk(client)
    Path("results/bloomberg.json").write_text(json.dumps(scenarios, default=date.isoformat, indent=2) + "\n")


if __name__ == "__main__":
    main()
